// Bundles the TypeScript engine into a single plain script for JavaScriptCore:
//   node scripts/build-engine-bundle.mjs [out]      (default: macos/Resources/engine.js)
// Needs only the `typescript` package, no native build tools.
// The script defines a global `Voka` (see src/engine/host.ts).
import fs from 'node:fs';
import path from 'node:path';
import { createRequire } from 'node:module';

const require = createRequire(import.meta.url);
const ts = require('typescript');

const ROOT = process.cwd();
const ENTRY = 'src/engine/jsc-entry.ts';
const OUT = path.join(ROOT, process.argv[2] ?? 'macos/Resources/engine.js');

const modules = new Map(); // module id -> { code, deps: { spec: id } }

function resolve(fromId, spec) {
  const base = path.posix.join(path.posix.dirname(fromId), spec);
  for (const candidate of [base + '.ts', base + '/index.ts']) {
    if (fs.existsSync(path.join(ROOT, candidate))) return candidate;
  }
  throw new Error(`cannot resolve "${spec}" from ${fromId}`);
}

function add(id) {
  if (modules.has(id)) return;
  const source = fs.readFileSync(path.join(ROOT, id), 'utf8');
  const { outputText } = ts.transpileModule(source, {
    fileName: id,
    compilerOptions: {
      module: ts.ModuleKind.CommonJS,
      target: ts.ScriptTarget.ES2019,
      esModuleInterop: false,
      removeComments: true,
    },
  });
  const record = { code: outputText, deps: {} };
  modules.set(id, record);
  for (const m of outputText.matchAll(/require\("([^"]+)"\)/g)) {
    const spec = m[1];
    if (!spec.startsWith('.')) {
      throw new Error(`${id} imports "${spec}": the engine bundle must not depend on packages`);
    }
    record.deps[spec] = resolve(id, spec);
    add(record.deps[spec]);
  }
}

add(ENTRY);

const parts = [];
parts.push('// Voka engine bundle - generated by scripts/build-engine-bundle.mjs, do not edit.');
parts.push('(function (global) {');
parts.push('"use strict";');
parts.push(
  'if (typeof global.console === "undefined") { var noop = function () {}; global.console = { log: noop, warn: noop, error: noop, info: noop, debug: noop }; }'
);
parts.push('var defs = {};');
parts.push('var maps = {};');
for (const [id, record] of modules) {
  parts.push(`defs[${JSON.stringify(id)}] = function (require, module, exports) {\n${record.code}\n};`);
  parts.push(`maps[${JSON.stringify(id)}] = ${JSON.stringify(record.deps)};`);
}
parts.push('var cache = {};');
parts.push(
  'function load(id) { var hit = cache[id]; if (hit) return hit.exports; var m = (cache[id] = { exports: {} }); defs[id](function (spec) { return load(maps[id][spec]); }, m, m.exports); return m.exports; }'
);
parts.push(`load(${JSON.stringify(ENTRY)});`);
parts.push('})(typeof globalThis !== "undefined" ? globalThis : this);');

fs.mkdirSync(path.dirname(OUT), { recursive: true });
fs.writeFileSync(OUT, parts.join('\n') + '\n');
console.log(
  `engine bundle: ${modules.size} modules -> ${path.relative(ROOT, OUT)} (${(fs.statSync(OUT).size / 1024).toFixed(0)} KB)`
);
